function normalize(value: string) {
  return value.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^\p{L}\p{N}\s]/gu, ' ').replace(/\s+/g, ' ').trim();
}
function distance(a: string, b: string) {
  const row = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i += 1) {
    let previous = row[0]; row[0] = i;
    for (let j = 1; j <= b.length; j += 1) {
      const saved = row[j]; row[j] = Math.min(row[j] + 1, row[j - 1] + 1, previous + (a[i - 1] === b[j - 1] ? 0 : 1)); previous = saved;
    }
  }
  return row[b.length];
}
function gradeAnswer(answer: string, expected: string, strictness: Strictness): GradeResult {
  const typed = normalize(answer);
  const variants = expected.split(/\s+\|\s+/).map((raw) => raw.trim()).filter(Boolean).map((raw) => ({ raw, normalized: normalize(raw) }));
  if (!typed) return { kind: 'wrong', reason: 'No answer was entered.' };
  const exact = variants.find((variant) => variant.normalized === typed);
  if (exact) return exact.raw === expected ? { kind: 'correct', reason: 'Exact match.', matchedExpected: exact.raw } : { kind: 'correct', reason: 'Accepted as an alternate answer.', matchedExpected: exact.raw };
  if (strictness !== 'strict') {
    const coverage = strictness === 'lenient' ? 0.45 : 0.62;
    const partial = variants.find((variant) => typed.split(' ').length >= 2 && variant.normalized.includes(typed) && typed.length / Math.max(variant.normalized.length, 1) >= coverage);
    if (partial) return { kind: 'close', reason: 'Accepted as a substantial matching phrase.', matchedExpected: partial.raw };
  }
  const ratio = strictness === 'lenient' ? 0.22 : strictness === 'balanced' ? 0.16 : 0.08;
  const ranked = variants.map((variant) => ({ ...variant, edits: distance(typed, variant.normalized), allowed: variant.normalized.length < (strictness === 'strict' ? 7 : 5) ? 0 : Math.max(1, Math.floor(variant.normalized.length * ratio)) })).sort((a, b) => a.edits - b.edits);
  const closest = ranked[0];
  if (closest && closest.edits <= closest.allowed) return { kind: 'close', reason: `Accepted as a typo: ${closest.edits} ${closest.edits === 1 ? 'edit' : 'edits'} within the ${strictness} limit of ${closest.allowed}.`, matchedExpected: closest.raw, distance: closest.edits, allowance: closest.allowed };
  return { kind: 'wrong', reason: `Outside the ${strictness} matching limit.`, matchedExpected: closest?.raw ?? expected };
}
function shuffle<T>(items: T[]) {
  const result = [...items];
  for (let i = result.length - 1; i > 0; i -= 1) { const j = Math.floor(Math.random() * (i + 1)); [result[i], result[j]] = [result[j], result[i]]; }
  return result;
}
function letterLabel(index: number) {
  let label = ''; let value = index + 1;
  while (value > 0) { value -= 1; label = String.fromCharCode(65 + (value % 26)) + label; value = Math.floor(value / 26); }
  return label;
}
function parseQuestionBank(text: string): BlindImport {
  const cards: Card[] = []; const invalidLines: number[] = []; const duplicateLines: number[] = []; const seenQuestions = new Set<string>(); let rowCount = 0;
  text.split(/\r?\n/).forEach((line, index) => {
    if (!line.trim()) return; rowCount += 1; const lineNumber = index + 1; const columns = line.split('\t').map((value) => value.trim());
    if (columns.length !== 5 || columns.some((value) => !value)) { invalidLines.push(lineNumber); return; }
    const [question, correct, wrongOne, wrongTwo, wrongThree] = columns;
    if (new Set([correct, wrongOne, wrongTwo, wrongThree].map(normalize)).size !== 4) { invalidLines.push(lineNumber); return; }
    const questionKey = normalize(question); if (seenQuestions.has(questionKey)) { duplicateLines.push(lineNumber); return; } seenQuestions.add(questionKey);
    cards.push({ id: lineNumber - 1, term: question, definition: correct, wrong: [wrongOne, wrongTwo, wrongThree], kind: 'question' });
  });
  if (!rowCount) return { status: 'error', cards: [], rowCount: 0, invalidLines: [], duplicateLines: [], message: 'The file is empty.' };
  return { status: invalidLines.length || duplicateLines.length ? 'error' : 'ready', cards, rowCount, invalidLines, duplicateLines };
}
function answerHint(expected: string) {
  const value = expected.split(/\s+\|\s+/)[0].trim(); const words = value.split(/\s+/).filter(Boolean); const first = words[0] ?? '';
  return `${first ? `${first[0]}${'•'.repeat(Math.min(Math.max(first.length - 1, 1), 12))}` : '—'}${words.length > 1 ? ` · ${words.length} words total` : ` · ${first.length} letters`}`;
}
function clozePrompt(card?: Card) {
  if (!card) return ''; const context = card.context?.trim();
  if (!context) return `Which word best fits this meaning? “${card.definition}”`;
  if (/\{\{term\}\}/i.test(context)) return context.replace(/\{\{term\}\}/gi, '_____');
  const escaped = card.term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  if (new RegExp(escaped, 'i').test(context)) return context.replace(new RegExp(escaped, 'gi'), '_____');
  return /_{3,}/.test(context) ? context : `${context}  _____`;
}
function makeJigsawPieces(definition: string, fine = false): JigsawPiece[] {
  const words = definition.trim().split(/\s+/).filter(Boolean); if (words.length <= 1) return [{ id: 0, text: definition }];
  const targetPieces = Math.min(fine ? 8 : 6, Math.max(2, Math.ceil(words.length / (fine ? 1.25 : 2)))); const chunkSize = Math.ceil(words.length / targetPieces); const pieces: JigsawPiece[] = [];
  for (let index = 0; index < words.length; index += chunkSize) pieces.push({ id: pieces.length, text: words.slice(index, index + chunkSize).join(' ') });
  return pieces;
}
function DifferenceText({ value, compare }: { value: string; compare: string }) {
  const tokens = value.split(/(\s+)/); const against = compare.split(/(\s+)/);
  return <>{tokens.map((token, index) => /^\s+$/.test(token) || normalize(token) === normalize(against[index] ?? '') ? <span key={`${token}-${index}`}>{token}</span> : <mark key={`${token}-${index}`}>{token}</mark>)}</>;
}
function HighlightedText({ value, highlights, interactive = false, onToggle }: { value: string; highlights: string[]; interactive?: boolean; onToggle?: (segment: string) => void }) {
  const normalizedHighlights = new Set(highlights.map((segment) => segment.toLowerCase()));
  if (interactive) return <>{value.split(/(\s+)/).map((segment, index) => /^\s+$/.test(segment) ? segment : <button type="button" className={`highlight-token ${normalizedHighlights.has(segment.toLowerCase()) ? 'active' : ''}`} onClick={() => onToggle?.(segment)} key={`${segment}-${index}`}>{segment}</button>)}</>;
  if (!highlights.length) return <>{value}</>; const escaped = highlights.filter(Boolean).sort((a, b) => b.length - a.length).map((segment) => segment.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'));
  if (!escaped.length) return <>{value}</>; const pattern = new RegExp(`(${escaped.join('|')})`, 'gi');
  return <>{value.split(pattern).map((segment, index) => normalizedHighlights.has(segment.toLowerCase()) ? <mark key={`${segment}-${index}`}>{segment}</mark> : <span key={`${segment}-${index}`}>{segment}</span>)}</>;
}

